const cap = s => (s ? s[0].toUpperCase() + s.slice(1) : s);
const inCity = city => (city ? ` в ${city}` : '');
const conciseInput = (value, limit = 240) => {
  const text = String(value || '').replace(/\s+/g, ' ').trim();
  if (text.length <= limit) return text;
  const sentences = text.split(/(?<=[.!?])\s+/).slice(0, 2).join(' ');
  if (sentences.length <= limit) return sentences;
  const clipped = text.slice(0, limit - 1).replace(/\s+\S*$/, '').trim();
  return clipped ? `${clipped}…` : text.slice(0, limit - 1) + '…';
};
const OWNER_BRIEF_LIMIT = 2000;
const inputObject = value => value && typeof value === 'object' && !Array.isArray(value) ? value : {};
const ownerBrief = value => {
  const text = String(value || '').replace(/\s+/g, ' ').trim();
  if (text.length <= OWNER_BRIEF_LIMIT) return text;
  const clipped = text.slice(0, OWNER_BRIEF_LIMIT - 1).replace(/\s+\S*$/, '').trim();
  return (clipped || text.slice(0, OWNER_BRIEF_LIMIT - 1)) + '…';
};
const inputHeadline = (value, fallback) => {
  const text = String(value || '').replace(/\s+/g, ' ').trim();
  if (!text) return fallback;
  const first = text.split(/[.!?\n]/, 1)[0].trim();
  if (first.length >= 18 && first.length <= 72) return first;
  const lead = first.split(/\s+[—–:]\s+|[,;]/, 1)[0].trim();
  return lead.length >= 18 && lead.length <= 72 ? lead : fallback;
};
function parseProvidedItems(value) {
  if (Array.isArray(value)) return value.slice(0, 12).filter(item => item && (typeof item === 'object' || String(item).trim()));
  return String(value || '').split(/\r?\n/).map(line => line.replace(/^\s*[-*•]\s*/, '').trim()).filter(Boolean).slice(0, 12).map(line => {
    const [title, ...description] = line.split('|');
    return { title: title.trim().slice(0, 100), text: description.join('|').trim().slice(0, 280) };
  }).filter(item => item.title);
}
const removeDraftPlaceholders = value => String(value || '').replace(/\s*\[[^\]]*\]\s*/g, ' ').replace(/\s+/g, ' ').trim();
const publishableDraftText = value => {
  const text = removeDraftPlaceholders(value);
  return /\b(?:укажите|добавьте|опишите|подтвердите|расскажите|уточните)\b/i.test(text) ? '' : text;
};
const publishableDraftPairs = rows => (rows || []).filter(row =>
  Array.isArray(row) && !row.some(value => /\[[^\]]*\]|\b(?:укажите|добавьте|опишите|подтвердите|расскажите|уточните)\b/i.test(String(value || '')))
);

