/**
 * Подсказки для реальной фотосъёмки. Это творческое направление, не утверждение о наличии
 * у бизнеса конкретных товаров, помещений или сотрудников.
 */
function photoPlan(niche, direction, tier) {
  const subject = niche.toLowerCase();
  const look = direction || 'естественный свет, выразительная композиция и честные детали';
  const finish = tier === 'luxury'
    ? 'редакционная съёмка, мягкий направленный свет, точная композиция, много воздуха, естественная фактура, без визуального шума'
    : tier === 'premium'
      ? 'профессиональный естественный свет, аккуратный фон, внимание к фактуре и деталям, спокойная композиция'
      : 'чистый естественный свет, понятный сюжет, живые цвета и аккуратный фон';
  return [
    `Первый экран: главный выразительный кадр для сайта о «${subject}». ${look}. Широкий горизонтальный кадр 16:9, главный объект смещён от центра, оставьте спокойное пространство под заголовок. ${finish}.`,
    `Главный объект крупно: предмет, продукт или результат работы в нише «${subject}». Покажите материал, фактуру и реальные детали; вертикальный кадр 4:5, мягкий боковой свет, без надписей и водяных знаков.`,
    `Процесс: руки мастера или ключевой этап работы в нише «${subject}». Снимите естественный момент с близкого расстояния, фон не отвлекает, вертикальный кадр 4:5. Не изображайте процесс, которого в действительности нет.`,
    `Люди и взаимодействие: человек в естественной ситуации, связанной с «${subject}». Живой взгляд и спокойная эмоция, без постановочной стоковой улыбки; вертикальный кадр 4:5. Используйте только реальных людей с их согласием.`,
    `Атмосфера и детали: пространство, инструменты или детали, которые помогают почувствовать «${subject}». Снимите несколько спокойных кадров с разной дистанции, горизонтальный и вертикальный форматы. ${finish}.`,
  ];
}

/**
 * Собирает проект по одной нише.
 * @param {{niche:string, brand?:string, city?:string, details?:string, email?:string, phone?:string}} input
 * @returns {{project:object, analysis:object}}
 */
export function draftFromNiche(input = {}) {
  input = inputObject(input);
  const niche = str(input.niche).replace(/\s+/g, ' ');
  if (!niche) throw new TypeError('Укажите нишу');
  const city = str(input.city);
  const details = str(input.details);
  const mainOffer = conciseInput(input.mainOffer, 500);
  const targetAudience = conciseInput(input.targetAudience, 360);
  const providedServices = parseProvidedItems(input.services);
  const profile = detectNiche({ niche, brand: str(input.brand), description: `${details} ${mainOffer}`, mainOffer });
  const pack = PACKS[profile.id] || PACKS.generic;
  const ctx = { n: niche.toLowerCase(), c: inCity(city) };
  const brand = str(input.brand);
  const tier = tierOf(input.tier);
  const t = TIER_COPY[tier];
  const draftSections = {
    services: providedServices.length ? providedServices : publishableDraftPairs(pack.items),
    advantages: publishableDraftPairs(t ? [t.advantage, ...pack.advantages.slice(0, 2)] : pack.advantages),
    process: publishableDraftPairs(pack.process),
    faqs: publishableDraftPairs(pack.faqs),
  };
  const omittedSections = [
    !providedServices.length && draftSections.services.length < pack.items.length ? 'каталог услуг' : '',
    draftSections.advantages.length < (t ? [t.advantage, ...pack.advantages.slice(0, 2)] : pack.advantages).length ? 'преимущества' : '',
    draftSections.process.length < pack.process.length ? 'этапы работы' : '',
    draftSections.faqs.length < pack.faqs.length ? 'FAQ' : '',
  ].filter(Boolean);
  const fallbackDescription = details
    ? conciseInput(details)
    : publishableDraftText(fill(pack.sub, ctx)) || `${cap(niche)} — ${profile.label.toLowerCase()}.`;
  const assumptions = [
    'Тексты собраны автопилотом по типовым задачам ниши — проверьте формулировки и замените гипотезы фактами бизнеса',
    'Подтвердите наличие каждой указанной услуги и условия доставки, записи, оплаты, сроков и гарантии перед публикацией',
    ...(providedServices.length ? [] : ['Позиции каталога или услуг — типовые для ниши; оставьте только реальные и уберите лишнее']),
  ];
  if (!brand) assumptions.push('Название бренда не указано — используется рабочее название');
  if (!city) assumptions.push('Город не указан — тексты без привязки к месту');
  if (!input.email && !input.phone) assumptions.push('Контакты не указаны — без них страница не принимает заявки');
  if (details.length > OWNER_BRIEF_LIMIT) assumptions.push(`Дополнительный бриф сокращён до ${OWNER_BRIEF_LIMIT} символов, чтобы не обрезать формат генерации.`);
  if (str(input.mainOffer).length > 500) assumptions.push('Основное предложение сокращено до 500 символов для генерации; полный вариант можно сохранить в дополнительном брифе.');
  if (str(input.targetAudience).length > 360) assumptions.push('Описание аудитории сокращено до 360 символов для генерации.');
  if (t) assumptions.push(t.confirm);
  if (omittedSections.length) assumptions.push(`Из черновика скрыты шаблонные или требующие подтверждения пункты (${omittedSections.join(', ')}); добавьте в эти разделы фактические данные бизнеса, если они нужны.`);

  const project = {
    formatVersion: 2,
    id: `auto-${Date.now().toString(36)}`,
    brand: brand || `${cap(niche)}${city ? ' · ' + city : ''}`,
    niche,
    tier,
    customPrompt: str(input.customPrompt), customPromptMode: input.customPromptMode === 'replace' ? 'replace' : 'append',
    contentDraftSource: 'local-autopilot',
    ...(details ? { ownerBrief: ownerBrief(details) } : {}),
    ...(providedServices.length ? { servicesProvidedByOwner: true } : {}),
    title: inputHeadline(mainOffer || details, pack.title),
    description: fallbackDescription,
    cta: pack.cta,
    mainOffer: mainOffer || conciseInput(details, 360) || fallbackDescription,
    targetAudience: targetAudience || `${cap(profile.audience)}.`,
    primaryGoal: profile.goal,
    brandCharacter: t ? `${profile.tone}; ${t.tone}` : profile.tone,
    servicesTitle: pack.itemsTitle,
    servicesIntro: providedServices.length
      ? 'Направления, указанные владельцем проекта.'
      : 'Предварительные направления по выбранной нише.',
    services: draftSections.services,
    aboutTitle: brand ? `О ${brand}` : 'О нас',
    aboutText: removeDraftPlaceholders(`${brand || 'Мы'} — ${profile.label.toLowerCase()}${inCity(city)}. ${cap(profile.why)}. ${t ? t.about + ' ' : ''}`),
    advantagesTitle: 'Как мы работаем',
    advantages: draftSections.advantages,
    processTitle: 'Путь к результату',
    process: draftSections.process,
    faqTitle: 'Частые вопросы',
    faqs: draftSections.faqs,
    contactTitle: 'Свяжитесь с нами',
    contactText: input.email || input.phone ? 'Свяжитесь удобным способом — контакты указаны ниже.' : '',
    contacts: { email: str(input.email), phone: str(input.phone) },
    assumptions,
    ...(Array.isArray(input.designReferences) && input.designReferences.length ? { designReferences: input.designReferences } : {}),
  };

  const analysis = {
    source: 'local', niche, city, tier, profileId: profile.id, businessType: profile.label,
    goal: profile.goal, audience: targetAudience || profile.audience, tone: t ? `${profile.tone}; ${t.tone}` : profile.tone,
    segments: pack.segments.map(([name, need]) => ({ name, need })),
    jobs: profile.priority,
    objections: pack.objections,
    triggers: pack.triggers,
    keywords: pack.keywords.map(k => fill(k, ctx).replace(/\s+/g, ' ').trim()),
    seo: {
      title: `${cap(niche)}${inCity(city)} — ${brand || pack.cta.toLowerCase()}`.slice(0, 70),
      description: conciseInput(details || mainOffer || fill(pack.sub, ctx), 160),
    },
    imageDirection: profile.image,
    imagePrompts: photoPlan(niche, profile.image, tier),
  };
  return { project, analysis };
}

/** ТЗ на главную страницу в Markdown — по анализу и концепции движка. */
export function buildSpec(projectInput, concept, analysis) {
  const p = normalizeProject(projectInput);
  const d = concept.designDNA, h = concept.homepage, b = concept.designBrief;
  const a = analysis || {};
  const li = arr => (Array.isArray(arr) ? arr : []).slice(0, 50)
    .map(value => `- ${String(value ?? '').replace(/[\u0000-\u001f\u007f]/g, ' ').slice(0, 500)}`)
    .join('\n') || '- —';
  const sourceNotes = (Array.isArray(a.sources) ? a.sources : []).slice(0, 10).flatMap(source => {
    const url = safeUrl(source?.url);
    if (!url || !/^https:\/\//i.test(url)) return [];
    const title = str(source?.title).replace(/[\r\n<>`\[\]]/g, ' ').slice(0, 120) || new URL(url).hostname;
    return [`- ${title} — ${url}`];
  }).join('\n');
  return `# ТЗ: главная страница «${p.brand}»

## 1. Задача
${b.businessType}${a.city ? `, ${a.city}` : ''}. Ниша: ${p.niche}. Класс: **${TIERS[p.tier]}**.
Цель страницы: ${b.primaryGoal}. Основное действие — «${h.primaryCTA}».

## 2. Аудитория (гипотеза)
${b.audience}
${a.segments ? '\nСегменты:\n' + a.segments.map(s => `- **${s.name}** — ${s.need}`).join('\n') : ''}
${a.objections ? '\nВозражения, которые страница должна снять:\n' + li(a.objections) : ''}
${a.triggers ? '\nПоводы обратиться:\n' + li(a.triggers) : ''}

## 3. Приоритет контента
${li(b.contentPriority)}
${a.marketResearch ? `\n## Исследование рынка (внешние данные)\n<research-data>\n${String(a.marketResearch).slice(0, 8000).replace(/<\/research-data/gi, '&lt;/research-data')}\n</research-data>\n` : ''}${a.competitors && a.competitors.length ? `\nКонкуренты и типовые подходы:\n${li(a.competitors)}\n` : ''}${sourceNotes ? `\nИсточники (URL проверены):\n${sourceNotes}\n` : ''}

## 4. Концепция (Design DNA)
${d.conceptName ? `- Концепция: **${d.conceptName}** — ${d.conceptFormula}\n` : ''}- Архитектура: **${ARCHETYPES[d.primaryArchetype].name}**${d.secondaryArchetype ? `, вспомогательная — ${ARCHETYPES[d.secondaryArchetype].name}` : ''}
- Почему: ${d.selectionRationale}
- Первый экран: ${h.heroComposition}
- Навигация: ${h.navigationPattern}
- Цвет: ${d.colorDirection}
- Типографика: ${d.typographyDirection}
- Изображения: ${d.imageDirection}
- Движение: ${d.motionDirection}
${concept.visualSystem?.cinematicLayers ? `- Фактура и свет: ${describeCinematicLayers(concept.visualSystem.cinematicLayers)}\n` : ''}${concept.visualSystem?.transition ? `- Переходы между секциями: ${describeTransition(concept.visualSystem.transition)}\n` : ''}${concept.libraryUse ? `
### Профили библиотеки шаблонов
Изучены: ${concept.libraryUse.references.map(r => `«${r.name}» (${r.category})`).join(', ')}. Использованы принципы, не готовый дизайн.

Что применено:
${li(concept.libraryUse.applied)}

Решения для переосмысления:
${li([...concept.libraryUse.patterns.structure, ...concept.libraryUse.patterns.ux, ...concept.libraryUse.patterns.content])}

Чем проект отличается:
${li(concept.libraryUse.divergence)}
` : ''}

## 5. План фотосъёмки\n${li(a.imagePrompts)}\n\n## 6. Структура страницы
${h.sections.map((s, i) => `${i + 1}. **${s.id}** — ${s.role}`).join('\n')}

## 7. SEO
- Title: ${a.seo ? a.seo.title : p.title}
- Description: ${a.seo ? a.seo.description : p.description}
- Ключевые запросы (проверить в Вордстате): ${(a.keywords || []).join(', ') || '—'}

## 8. Технические требования
- Адаптивность от 320 px, без горизонтальной прокрутки
- Доступность: семантика, видимый фокус, подписи полей, контраст WCAG AA, prefers-reduced-motion
- Один основной CTA на экран; форма заявки работает только при указанных контактах или formAction

## 9. Что уточнить у владельца
${li([...b.assumptions, 'Реальные позиции, цены и сроки', 'Фото работ или продукта (вместо графических мотивов)', 'Подтверждения доверия: опыт, документы, реальные отзывы со ссылкой на источник', 'Контакты, адрес, часы работы, реквизиты'])}
`;
}

/** Всё за один вызов: проект → концепция → ТЗ и промт. Сборка HTML — обычным generate(). */
export function autopilot(input, { registry = [], forWorker = false } = {}) {
  input = inputObject(input);
  const { project, analysis } = draftFromNiche(input);
  const concept = buildConcept(project, { registry, references: input.designReferences });
  return { project, analysis, concept, spec: buildSpec(project, concept, analysis), prompt: buildPrompt(project, concept, analysis, { forWorker }) };
}

/**
 * Превращает ответ AI-сервера (/api/generate-landing с веб-поиском) в проект и анализ.
 * Палитру, акцент и стиль из ответа не берём: внешний вид выбирает движок с проверкой на повторы.
 */
export function fromAiLanding(landing, input = {}) {
  input = inputObject(input);
  const l = landing && typeof landing === 'object' ? landing : {};
  const pairs = v => (Array.isArray(v) ? v : typeof v === 'string' ? v.split(/\r?\n/).map(row => row.trim()).filter(Boolean) : []).slice(0, 24).map(row => {
    if (Array.isArray(row)) return row.map(value => str(value));
    if (typeof row === 'string') {
      const match = row.match(/^(.{1,100}?)\s*(?:\||[—–])\s*(.{1,600})$/);
      return match ? [match[1].trim(), match[2].trim()] : [str(row), ''];
    }
    if (!row || typeof row !== 'object') return null;
    const title = str(row.title ?? row.name ?? row.question ?? row.label);
    const text = str(row.text ?? row.description ?? row.answer ?? row.body);
    return { ...row, title, text };
  }).filter(row => Array.isArray(row) ? row.some(Boolean) : row && (row.title || row.text));
  const localFallback = draftFromNiche({ ...input, niche: str(input.niche) || str(l.niche) });
  const plannedSectionIds = Array.isArray(input.plannedSectionIds) ? new Set(input.plannedSectionIds.map(str)) : null;
  const hasSection = id => !plannedSectionIds || plannedSectionIds.has(id);
  const fallbackFields = [];
  const withFallback = (field, value, fallback) => {
    const current = str(value);
    if (current) return current;
    const safeFallback = str(fallback);
    if (safeFallback) fallbackFields.push(field);
    return safeFallback;
  };
  const aiAssumptions = Array.isArray(l.assumptions) ? l.assumptions : typeof l.assumptions === 'string' ? [l.assumptions] : [];
  const providedServices = parseProvidedItems(input.services);
  const tier = tierOf(input.tier || l.tier);
  const project = {
    formatVersion: 2, id: `ai-${Date.now().toString(36)}`,
    brand: str(input.brand) || str(l.brand), niche: str(input.niche) || str(l.niche), tier,
    customPrompt: str(input.customPrompt), customPromptMode: input.customPromptMode === 'replace' ? 'replace' : 'append',
    ...(str(input.details) ? { ownerBrief: ownerBrief(input.details) } : {}),
    title: withFallback('title', l.title, localFallback.project.title),
    description: withFallback('description', l.description, localFallback.project.description),
    cta: withFallback('cta', l.cta, localFallback.project.cta),
    seoTitle: withFallback('seoTitle', l.seoTitle, localFallback.analysis.seo.title.slice(0, 60)),
    seoDescription: withFallback('seoDescription', l.seoDescription, localFallback.analysis.seo.description),
    targetAudience: conciseInput(input.targetAudience, 360) || withFallback('targetAudience', l.targetAudience, localFallback.project.targetAudience),
    mainOffer: conciseInput(input.mainOffer, 500) || withFallback('mainOffer', l.mainOffer, localFallback.project.mainOffer),
    visualDirection: str(l.visualDirection), strategySummary: str(l.strategySummary),
    aboutTitle: hasSection('about') ? str(l.aboutTitle) : '',
    aboutText: hasSection('about') ? str(l.aboutText) : '',
    servicesTitle: hasSection('items') ? str(l.servicesTitle) : '',
    servicesIntro: hasSection('items') ? (providedServices.length ? 'Направления, указанные владельцем проекта.' : str(l.servicesIntro)) : '',
    services: providedServices.length ? providedServices : hasSection('items') ? pairs(l.services) : [],
    ...(providedServices.length ? { servicesProvidedByOwner: true } : {}),
    advantagesTitle: hasSection('advantages') ? str(l.advantagesTitle) : '',
    advantages: hasSection('advantages') ? pairs(l.advantages) : [],
    processTitle: hasSection('process') ? str(l.processTitle) : '',
    process: hasSection('process') ? pairs(l.process) : [],
    faqTitle: hasSection('faq') ? (str(l.faqTitle) || 'Частые вопросы') : '',
    faqs: hasSection('faq') ? pairs(l.faqs) : [],
    contactTitle: hasSection('contact') ? str(l.contactTitle) : '',
    contactText: hasSection('contact') ? str(l.contactText) : '',
    contacts: { email: str(input.email), phone: str(input.phone) },
    assumptions: [
      ...aiAssumptions.map(item => item && typeof item === 'object'
        ? str(item.text ?? item.note ?? item.message)
        : str(item)).filter(Boolean).slice(0, 50),
      ...(fallbackFields.length ? [`Поля ${fallbackFields.join(', ')} восстановлены локальным автопилотом, потому что AI-ответ их не содержал; проверьте эти черновые формулировки.`] : []),
      ...(str(input.details).length > OWNER_BRIEF_LIMIT ? [`Дополнительный бриф сокращён до ${OWNER_BRIEF_LIMIT} символов, чтобы сохранить полный формат генерации.`] : []),
      ...(str(input.mainOffer).length > 500 ? ['Основное предложение сокращено до 500 символов для генерации.'] : []),
      ...(str(input.targetAudience).length > 360 ? ['Описание аудитории сокращено до 360 символов для генерации.'] : []),
    ],
    marketResearch: str(l.marketResearch), researchSources: Array.isArray(l.researchSources) ? l.researchSources : [],
    ...(Array.isArray(input.designReferences) && input.designReferences.length ? { designReferences: input.designReferences } : {}),
  };
  if (LEGACY.includes(l.designArchitecture)) project.designArchitecture = l.designArchitecture;
  const list = v => (Array.isArray(v) ? v : typeof v === 'string' ? v.split(/\r?\n/) : []).slice(0, 50).map(item => {
    if (item && typeof item === 'object') return str(item.prompt ?? item.description ?? item.name ?? item.title ?? item.keyword ?? item.text);
    return String(item ?? '').trim();
  }).filter(Boolean);
  const analysis = {
    source: 'ai', niche: project.niche, city: str(input.city), tier,
    goal: str(l.strategySummary), audience: project.targetAudience,
    segments: (Array.isArray(l.segments) ? l.segments : []).slice(0, 20).map(segment => {
      if (Array.isArray(segment)) return { name: str(segment[0]), need: str(segment[1]) };
      if (typeof segment === 'string') return { name: str(segment), need: '' };
      return segment && typeof segment === 'object'
        ? { name: str(segment.name ?? segment.segment ?? segment.title), need: str(segment.need ?? segment.situation ?? segment.description) }
        : { name: '', need: '' };
    }).filter(segment => segment.name),
    objections: list(l.objections), triggers: list(l.triggers), keywords: list(l.keywords), competitors: list(l.competitors),
    marketResearch: project.marketResearch,
    sources: (Array.isArray(project.researchSources) ? project.researchSources : []).map(source => {
      const row = source && typeof source === 'object' ? source : { title: str(source), url: typeof source === 'string' ? source : '' };
      return { source: row, url: safeUrl(row.url) };
    })
      .filter(({ url }) => url && /^https:\/\//i.test(url))
      .map(({ source, url }) => ({ title: String(source.title || url), url })),
    seo: { title: str(l.seoTitle) || project.title, description: str(l.seoDescription) || project.description },
    imagePrompts: list(l.imagePrompts),
  };
  return { project, analysis };
}
const LEGACY = ['catalog', 'editorial', 'immersive', 'service', 'modular'];
